package com.v7.quantumfast; import android.content.pm.*; import android.os.Bundle; import android.view.*; import androidx.annotation.NonNull; import androidx.fragment.app.Fragment; import androidx.recyclerview.widget.*; import java.util.*;
public class Page1Fragment extends Fragment{ RecyclerView rv; public View onCreateView(@NonNull LayoutInflater inf,ViewGroup p,Bundle b){View v=inf.inflate(R.layout.fragment_page1,p,false);rv=v.findViewById(R.id.recyclerApps);rv.setLayoutManager(new GridLayoutManager(getContext(),4));try{PackageManager pm=requireContext().getPackageManager();List<ApplicationInfo> all=pm.getInstalledApplications(0);List<AppInfo> out=new ArrayList<>();for(ApplicationInfo ai:all){if(pm.getLaunchIntentForPackage(ai.packageName)!=null) out.add(new AppInfo(pm.getApplicationLabel(ai).toString(),ai.packageName,pm.getApplicationIcon(ai)));}Collections.sort(out,(a,c)->a.name.compareToIgnoreCase(c.name));rv.setAdapter(new AppAdapter(out));}catch(Exception e){}return v;}}
